                b.Entity(type.ClrType).Property(nameof(Owned.UserId)).HasMaxLength(36);
                b.Entity(type.ClrType).Property(nameof(Owned.Version)).IsConcurrencyToken();
                b.Entity(type.ClrType).HasOne(typeof(AppUser)).WithMany().HasForeignKey(nameof(Owned.UserId)).OnDelete(DeleteBehavior.NoAction);
            }
            foreach (var property in type.GetProperties())
            {
                if (property.ClrType == typeof(string) && (property.Name.EndsWith("Id", StringComparison.Ordinal))) property.SetMaxLength(36);
                if (property.ClrType == typeof(string) && property.Name is "Status" or "Type" or "Kind" or "State") property.SetMaxLength(40);
                if (property.Name == "Currency") property.SetMaxLength(3);
                if (property.ClrType == typeof(decimal) || property.ClrType == typeof(decimal?))
                { property.SetPrecision(28); property.SetScale(property.Name.Contains("Rate") ? 8 : 4); }
            }
